class Solution:
    def distinctIntegers(self, n: int) -> int:
        board = {n}
        while True:
            new = set(board)
            for x in board:
                for i in range(1, n + 1):
                    if x % i == 1:
                        new.add(i)
            if new == board:
                return len(board)
            board = new

