class Solution {
public:
    int distinctIntegers(int n) {
        unordered_set<int> board{n}, nxt;
        while (true) {
            nxt = board;
            for (int x : board)
                for (int i = 1; i <= n; i++)
                    if (x % i == 1) nxt.insert(i);
            if (nxt.size() == board.size()) return board.size();
            board = nxt;
        }
    }
};

c.java:
class Solution {
    public int distinctIntegers(int n) {
        Set<Integer> board = new HashSet<>(Set.of(n));
        while (true) {
            Set<Integer> nxt = new HashSet<>(board);
            for (int x : board)
                for (int i = 1; i <= n; i++)
                    if (x % i == 1) nxt.add(i);
            if (nxt.equals(board)) return board.size();
            board = nxt;
        }
    }
}

